<script>
import BaseComponent from '@primevue/core/basecomponent';
import Button from 'primevue/button';
import SidebarTriggerStyle from 'primevue/sidebartrigger/style';

export default {
    name: 'BaseSidebarTrigger',
    extends: BaseComponent,
    props: {
        target: {
            type: String,
            default: undefined
        },
        as: {
            type: [String, Object, Function],
            default: () => Button
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: SidebarTriggerStyle,
    provide() {
        return {
            $pcSidebarTrigger: this,
            $parentInstance: this
        };
    }
};
</script>
